// LatestTagInMajor returns the newest stable release tag of major for
// owner/repo. Drafts, prereleases, and tags that are not semver are skipped.
func (g *GitHub) LatestTagInMajor(ctx context.Context, owner, repo string, major uint64) (string, error) {
	for page := 1; page <= maxReleasePages; page++ {
		rels, err := g.listReleases(ctx, owner, repo, page)
		if err != nil {
