new='''// releasesServer answers the release-list endpoint for o/r with pages, one
// JSON array per page, and counts the requests it serves.
func releasesServer(t *testing.T, pages ...string) (*httptest.Server, *int) {
	t.Helper()
	var hits int
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/repos/o/r/releases" {
			http.NotFound(w, r)
			return
		}
		hits++
		page, _ := strconv.Atoi(r.URL.Query().Get("page"))
		body := "[]"
		if page >= 1 && page <= len(pages) {
			body = pages[page-1]
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = io.WriteString(w, body)
	}))
	t.Cleanup(srv.Close)
	return srv, &hits
}

// fullPage pads a release page to releasesPerPage with releases of another
// major, so the scan cannot treat it as the last page.
func fullPage(rels ...string) string {
	for len(rels) < releasesPerPage {
		rels = append(rels, `{"tag_name":"v9.0.`+strconv.Itoa(len(rels))+`"}`)
	}
	return "[" + strings.Join(rels, ",") + "]"
}

func TestLatestTagInMajor(t *testing.T) {
	tests := []struct {
		name  string
		pages []string
		want  string
	}{
		{
			name:  "newer major is skipped",
			pages: []string{`[{"tag_name":"v2.0.0"},{"tag_name":"v1.2.0"},{"tag_name":"v1.1.0"}]`},
			want:  "v1.2.0",
		},
		{
			name: "prereleases and drafts are skipped",
			pages: []string{`[
				{"tag_name":"v1.3.0-beta.7","prerelease":true},
				{"tag_name":"v1.3.0","draft":true},
				{"tag_name":"v1.3.0-rc.1"},
				{"tag_name":"v1.2.0"}]`},
			want: "v1.2.0",
		},
		{
			name:  "backported patch does not win over a newer minor",
			pages: []string{`[{"tag_name":"v1.1.5"},{"tag_name":"v1.2.0"}]`},
			want:  "v1.2.0",
		},
		{
			name:  "non-semver tags are ignored",
			pages: []string{`[{"tag_name":"nightly"},{"tag_name":"v1.0.1"}]`},
			want:  "v1.0.1",
		},
		{
			name:  "match on a later page",
			pages: []string{fullPage(), `[{"tag_name":"v1.4.2"}]`},
			want:  "v1.4.2",
		},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			srv, _ := releasesServer(t, tc.pages...)
			g := NewGitHubClient(srv.Client(), "test", srv.URL)
			tag, err := g.LatestTagInMajor(context.Background(), "o", "r", 1)
			if err != nil {
				t.Fatal(err)
			}
			if tag != tc.want {
				t.Errorf("tag = %q, want %q", tag, tc.want)
			}
		})
	}
}

// An unpinned resolution uses the CLI's supported major, not the newest
// release overall.
func TestResolveTagUsesSupportedMajor(t *testing.T) {
	next := "v" + strconv.Itoa(SupportedTemplateMajor+1) + ".0.0"
	want := "v" + strconv.Itoa(SupportedTemplateMajor) + ".4.0"
	srv, _ := releasesServer(t, `[{"tag_name":"`+next+`"},{"tag_name":"`+want+`"}]`)
	g := NewGitHubClient(srv.Client(), "test", srv.URL)

	tag, err := g.ResolveTag(context.Background(), "o", "r", "")
	if err != nil {
		t.Fatal(err)
	}
	if tag != want {
		t.Errorf("tag = %q, want %q", tag, want)
	}
}

// The scan stops at the page cap: an outdated CLI must not walk the whole
// release history on every command.
func TestLatestTagInMajorStopsAtPageCap(t *testing.T) {
	pages := make([]string, maxReleasePages+1)
	for i := range pages {
		pages[i] = fullPage()
	}
	pages[maxReleasePages] = `[{"tag_name":"v1.0.0"}]`
	srv, hits := releasesServer(t, pages...)
	g := NewGitHubClient(srv.Client(), "test", srv.URL)

	_, err := g.LatestTagInMajor(context.Background(), "o", "r", 1)
	if err == nil {
		t.Fatal("expected an error past the page cap")
	}
	if !strings.Contains(err.Error(), "major version 1") {
		t.Errorf("error should name the major: %v", err)
	}
	if *hits != maxReleasePages {
		t.Errorf("requests = %d, want %d", *hits, maxReleasePages)
	}
}

func TestLatestTagInMajorNoMatch(t *testing.T) {
	srv, hits := releasesServer(t, `[{"tag_name":"v2.0.0"}]`)
	g := NewGitHubClient(srv.Client(), "test", srv.URL)

	if _, err := g.LatestTagInMajor(context.Background(), "o", "r", 1); err == nil {
		t.Fatal("expected an error when no release matches the major")
	}
	if *hits != 1 {
		t.Errorf("requests = %d, want 1: a short page is the last", *hits)
	}
}

func TestLatestTagInMajorHTTPError(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		http.Error(w, "not found", http.StatusNotFound)
	}))
	defer srv.Close()

	g := NewGitHubClient(srv.Client(), "test", srv.URL)
	if _, err := g.LatestTagInMajor(context.Background(), "o", "r", 1); err == nil {
		t.Fatal("expected error")
	}
}

