// A cached release of another major is never the offline answer: the network
// path would not have picked it, so the cache must not either.
func TestNewestCachedTagSkipsOtherMajors(t *testing.T) {
	lib := newTestLibrary(t, "v1.0.0", fetchTestFiles)
	next := "v" + strconv.Itoa(SupportedTemplateMajor+1) + ".0.0"
	lib.addRelease(t, next, map[string]string{"next.txt": "breaking\n"})
	cache := t.TempDir()

	for _, tag := range []string{"v1.0.0", next} {
		opts := lib.sourceOpts(cache, nil)
		opts.Version = tag
		if _, err := FetchSource(context.Background(), opts); err != nil {
			t.Fatalf("prime %s: %v", tag, err)
		}
	}
	if got := newestCachedTag(cache, "file://"+lib.repo); got != "v1.0.0" {
		t.Errorf("newestCachedTag = %q, want v1.0.0", got)
	}
}

